/* ============================================
   Volta Studio — Corporate Website Styles
   Minimal, editorial, warm
   ============================================ */

/* Google Fonts */
@import url('https://fonts.googleapis.com/css2?family=Playfair+Display:ital,wght@0,400;0,500;0,600;0,700;1,400;1,500&family=Inter:wght@300;400;500;600&display=swap');

/* CSS Variables */
:root {
  --bg-primary: #F5F2ED;
  --bg-warm: #F0EBE3;
  --text-primary: #1A1A1A;
  --text-secondary: #5C5C5C;
  --text-muted: #8A8A8A;
  --accent-terracotta: #C67B5C;
  --accent-sage: #8FA68E;
  --accent-sand: #D4C4A8;
  --accent-clay: #B8836F;
  --border-light: #E5E0D8;
  --font-serif: 'Playfair Display', Georgia, 'Times New Roman', serif;
  --font-sans: 'Inter', -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, sans-serif;
  --transition-smooth: cubic-bezier(0.4, 0, 0.2, 1);
}

/* Reset & Base */
*, *::before, *::after {
  margin: 0;
  padding: 0;
  box-sizing: border-box;
}

html {
  scroll-behavior: smooth;
  font-size: 16px;
}

body {
  font-family: var(--font-sans);
  background-color: var(--bg-primary);
  color: var(--text-primary);
  line-height: 1.6;
  -webkit-font-smoothing: antialiased;
  -moz-osx-font-smoothing: grayscale;
  overflow-x: hidden;
}

a {
  color: inherit;
  text-decoration: none;
}

img {
  max-width: 100%;
  display: block;
}

/* ============================================
   HEADER & NAVIGATION
   ============================================ */

.site-header {
  position: fixed;
  top: 0;
  left: 0;
  right: 0;
  z-index: 100;
  padding: 1.5rem 2.5rem;
  display: flex;
  justify-content: space-between;
  align-items: center;
  background: rgba(245, 242, 237, 0.92);
  backdrop-filter: blur(12px);
  -webkit-backdrop-filter: blur(12px);
  border-bottom: 1px solid transparent;
  transition: border-color 0.3s var(--transition-smooth);
}

.site-header.scrolled {
  border-bottom-color: var(--border-light);
}

.logo {
  font-family: var(--font-serif);
  font-size: 1.25rem;
  font-weight: 600;
  letter-spacing: -0.02em;
  color: var(--text-primary);
}

.logo a:hover {
  opacity: 0.7;
  transition: opacity 0.3s var(--transition-smooth);
}

.desktop-nav {
  display: flex;
  gap: 2.5rem;
  align-items: center;
}

.desktop-nav a {
  font-family: var(--font-sans);
  font-size: 0.875rem;
  font-weight: 400;
  letter-spacing: 0.02em;
  color: var(--text-secondary);
  position: relative;
  padding-bottom: 2px;
  transition: color 0.3s var(--transition-smooth);
}

.desktop-nav a::after {
  content: '';
  position: absolute;
  bottom: 0;
  left: 0;
  width: 0;
  height: 1px;
  background: var(--text-primary);
  transition: width 0.4s var(--transition-smooth);
}

.desktop-nav a:hover,
.desktop-nav a.active {
  color: var(--text-primary);
}

.desktop-nav a:hover::after,
.desktop-nav a.active::after {
  width: 100%;
}

/* Mobile Menu Toggle */
.menu-toggle {
  display: none;
  flex-direction: column;
  justify-content: center;
  align-items: center;
  width: 32px;
  height: 32px;
  cursor: pointer;
  z-index: 110;
  background: none;
  border: none;
  padding: 0;
}

.menu-toggle span {
  display: block;
  width: 22px;
  height: 1.5px;
  background: var(--text-primary);
  margin: 3px 0;
  transition: all 0.4s var(--transition-smooth);
  transform-origin: center;
}

.menu-toggle.open span:nth-child(1) {
  transform: translateY(4.5px) rotate(45deg);
}

.menu-toggle.open span:nth-child(2) {
  opacity: 0;
  transform: scaleX(0);
}

.menu-toggle.open span:nth-child(3) {
  transform: translateY(-4.5px) rotate(-45deg);
}

/* Mobile Overlay Menu */
.mobile-overlay {
  position: fixed;
  inset: 0;
  background: var(--bg-primary);
  z-index: 90;
  display: flex;
  flex-direction: column;
  justify-content: center;
  align-items: center;
  gap: 2rem;
  opacity: 0;
  pointer-events: none;
  transition: opacity 0.5s var(--transition-smooth);
}

.mobile-overlay.open {
  opacity: 1;
  pointer-events: all;
}

.mobile-overlay a {
  font-family: var(--font-serif);
  font-size: 2.5rem;
  font-weight: 500;
  color: var(--text-primary);
  opacity: 0;
  transform: translateY(20px);
  transition: opacity 0.5s var(--transition-smooth), transform 0.5s var(--transition-smooth), color 0.3s;
}

.mobile-overlay.open a {
  opacity: 1;
  transform: translateY(0);
}

.mobile-overlay.open a:nth-child(1) { transition-delay: 0.1s; }
.mobile-overlay.open a:nth-child(2) { transition-delay: 0.18s; }
.mobile-overlay.open a:nth-child(3) { transition-delay: 0.26s; }
.mobile-overlay.open a:nth-child(4) { transition-delay: 0.34s; }
.mobile-overlay.open a:nth-child(5) { transition-delay: 0.42s; }

.mobile-overlay a:hover {
  color: var(--accent-terracotta);
}

/* ============================================
   MAIN CONTENT SPACING
   ============================================ */

main {
  padding-top: 80px;
}

.section {
  padding: 6rem 2.5rem;
  max-width: 1400px;
  margin: 0 auto;
}

.section-narrow {
  max-width: 720px;
  margin: 0 auto;
  padding: 6rem 2.5rem;
}

/* ============================================
   TYPOGRAPHY
   ============================================ */

.heading-xl {
  font-family: var(--font-serif);
  font-size: clamp(2.5rem, 6vw, 5rem);
  font-weight: 600;
  line-height: 1.1;
  letter-spacing: -0.03em;
  color: var(--text-primary);
}

.heading-lg {
  font-family: var(--font-serif);
  font-size: clamp(2rem, 4.5vw, 3.5rem);
  font-weight: 600;
  line-height: 1.15;
  letter-spacing: -0.02em;
  color: var(--text-primary);
}

.heading-md {
  font-family: var(--font-serif);
  font-size: clamp(1.5rem, 3vw, 2.25rem);
  font-weight: 600;
  line-height: 1.2;
  letter-spacing: -0.01em;
  color: var(--text-primary);
}

.heading-sm {
  font-family: var(--font-sans);
  font-size: 0.75rem;
  font-weight: 500;
  letter-spacing: 0.15em;
  text-transform: uppercase;
  color: var(--text-muted);
}

.body-lg {
  font-family: var(--font-sans);
  font-size: 1.125rem;
  font-weight: 300;
  line-height: 1.7;
  color: var(--text-secondary);
}

.body-md {
  font-family: var(--font-sans);
  font-size: 1rem;
  font-weight: 400;
  line-height: 1.7;
  color: var(--text-secondary);
}

/* ============================================
   HERO SECTION
   ============================================ */

.hero {
  min-height: calc(100vh - 80px);
  display: flex;
  flex-direction: column;
  justify-content: center;
  padding: 4rem 2.5rem 6rem;
  max-width: 1400px;
  margin: 0 auto;
}

.hero-title {
  font-family: var(--font-serif);
  font-size: clamp(2.5rem, 7vw, 6rem);
  font-weight: 600;
  line-height: 1.08;
  letter-spacing: -0.03em;
  color: var(--text-primary);
  max-width: 900px;
}

/* ============================================
   MEDIA SHOWCASE
   ============================================ */

.media-showcase {
  width: 100%;
  padding: 0 2.5rem 4rem;
}

.media-triptych {
  display: grid;
  grid-template-columns: 1fr 1.2fr 1fr;
  gap: 1.5rem;
  max-width: 1400px;
  margin: 0 auto;
}

.media-block {
  aspect-ratio: 4/5;
  border-radius: 4px;
  overflow: hidden;
  position: relative;
}

.media-block--terracotta { background: var(--accent-terracotta); }
.media-block--sage { background: var(--accent-sage); }
.media-block--sand { background: var(--accent-sand); }

/* ============================================
   CLIENT MARQUEE
   ============================================ */

.marquee-section {
  padding: 4rem 0;
  overflow: hidden;
  border-top: 1px solid var(--border-light);
  border-bottom: 1px solid var(--border-light);
}

.marquee-row {
  display: flex;
  white-space: nowrap;
  padding: 1.25rem 0;
  will-change: transform;
}

.marquee-row:nth-child(odd) .marquee-track {
  animation: marquee-left 35s linear infinite;
}

.marquee-row:nth-child(even) .marquee-track {
  animation: marquee-right 35s linear infinite;
}

.marquee-track {
  display: flex;
  align-items: center;
  gap: 0;
}

.marquee-item {
  font-family: var(--font-serif);
  font-size: clamp(1.75rem, 4vw, 3rem);
  font-weight: 500;
  color: var(--text-primary);
  letter-spacing: -0.02em;
  padding: 0 2.5rem;
  flex-shrink: 0;
}

.marquee-separator {
  font-family: var(--font-serif);
  font-size: clamp(1.5rem, 3vw, 2.5rem);
  color: var(--text-muted);
  opacity: 0.4;
  padding: 0 0.5rem;
  flex-shrink: 0;
}

@keyframes marquee-left {
  0% { transform: translateX(0); }
  100% { transform: translateX(-50%); }
}

@keyframes marquee-right {
  0% { transform: translateX(-50%); }
  100% { transform: translateX(0); }
}

/* ============================================
   ABOUT SECTION
   ============================================ */

.about-section {
  padding: 6rem 2.5rem;
  max-width: 1400px;
  margin: 0 auto;
}

.about-grid {
  display: grid;
  grid-template-columns: 280px 1fr;
  gap: 4rem;
  align-items: start;
}

.about-label {
  font-family: var(--font-sans);
  font-size: 0.75rem;
  font-weight: 500;
  letter-spacing: 0.15em;
  text-transform: uppercase;
  color: var(--text-muted);
  padding-top: 0.5rem;
}

.about-body {
  max-width: 680px;
}

.about-body p + p {
  margin-top: 1.5rem;
}

/* ============================================
   FOUNDER LETTER (NEWENO)
   ============================================ */

.letter-header {
  padding: 4rem 2.5rem 2rem;
  max-width: 720px;
  margin: 0 auto;
}

.letter-header h1 {
  font-family: var(--font-serif);
  font-size: clamp(2rem, 5vw, 3.5rem);
  font-weight: 600;
  line-height: 1.15;
  letter-spacing: -0.02em;
}

.letter-content {
  max-width: 720px;
  margin: 0 auto;
  padding: 2rem 2.5rem 6rem;
}

.letter-content p {
  font-family: var(--font-sans);
  font-size: 1.0625rem;
  font-weight: 400;
  line-height: 1.85;
  color: var(--text-secondary);
  margin-bottom: 1.75rem;
}

.letter-content p:first-child::first-letter {
  font-family: var(--font-serif);
  font-size: 4rem;
  font-weight: 600;
  float: left;
  line-height: 0.8;
  padding-right: 0.75rem;
  padding-top: 0.25rem;
  color: var(--text-primary);
}

.letter-signature {
  font-family: var(--font-serif);
  font-size: 1.5rem;
  font-style: italic;
  color: var(--text-primary);
  margin-top: 3rem;
}

/* ============================================
   PHILOSOPHY SECTION
   ============================================ */

.philosophy-section {
  padding: 6rem 2.5rem;
  max-width: 1400px;
  margin: 0 auto;
}

.philosophy-grid {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 6rem;
  align-items: start;
}

.philosophy-label {
  font-family: var(--font-sans);
  font-size: 0.75rem;
  font-weight: 500;
  letter-spacing: 0.15em;
  text-transform: uppercase;
  color: var(--text-muted);
}

.philosophy-heading {
  font-family: var(--font-serif);
  font-size: clamp(2.5rem, 5vw, 4rem);
  font-weight: 600;
  line-height: 1.1;
  letter-spacing: -0.02em;
  margin-top: 1rem;
}

.philosophy-body {
  padding-top: 2rem;
}

.philosophy-body p + p {
  margin-top: 1.5rem;
}

/* Divider */
.section-divider {
  max-width: 1400px;
  margin: 0 auto;
  padding: 0 2.5rem;
}

.section-divider hr {
  border: none;
  height: 1px;
  background: var(--border-light);
}

/* ============================================
   SERVICES DETAILS
   ============================================ */

.services-section {
  padding: 6rem 2.5rem;
  max-width: 1400px;
  margin: 0 auto;
}

.services-heading {
  font-family: var(--font-serif);
  font-size: clamp(1.5rem, 3vw, 2.25rem);
  font-weight: 600;
  line-height: 1.25;
  margin-bottom: 4rem;
  max-width: 600px;
}

.service-list {
  display: flex;
  flex-direction: column;
  gap: 4rem;
}

.service-item {
  display: grid;
  grid-template-columns: 200px 1fr;
  gap: 3rem;
  align-items: start;
}

.service-name {
  font-family: var(--font-serif);
  font-size: 1.5rem;
  font-weight: 600;
  color: var(--text-primary);
}

.service-description {
  font-family: var(--font-sans);
  font-size: 1rem;
  font-weight: 400;
  line-height: 1.75;
  color: var(--text-secondary);
  max-width: 560px;
}

/* ============================================
   CLIENTS PAGE
   ============================================ */

.clients-hero {
  padding: 4rem 2.5rem 2rem;
  max-width: 1400px;
  margin: 0 auto;
}

.clients-hero h1 {
  font-family: var(--font-serif);
  font-size: clamp(2rem, 5vw, 3.5rem);
  font-weight: 600;
  line-height: 1.15;
  letter-spacing: -0.02em;
}

.clients-hero p {
  font-family: var(--font-sans);
  font-size: 1rem;
  color: var(--text-muted);
  margin-top: 0.75rem;
}

.clients-grid {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 3rem 2.5rem;
  padding: 4rem 2.5rem 6rem;
  max-width: 1400px;
  margin: 0 auto;
}

.client-card h3 {
  font-family: var(--font-serif);
  font-size: 1.375rem;
  font-weight: 600;
  color: var(--text-primary);
  margin-bottom: 0.5rem;
}

.client-card p {
  font-family: var(--font-sans);
  font-size: 0.9375rem;
  font-weight: 400;
  line-height: 1.65;
  color: var(--text-secondary);
}

/* ============================================
   CONTACT PAGE
   ============================================ */

.contact-page {
  min-height: 100vh;
  display: flex;
  flex-direction: column;
  justify-content: center;
  align-items: center;
  text-align: center;
  padding: 6rem 2.5rem;
}

.contact-heading {
  font-family: var(--font-serif);
  font-size: clamp(4rem, 15vw, 14rem);
  font-weight: 600;
  line-height: 1;
  letter-spacing: -0.04em;
  color: var(--text-primary);
}

.contact-links {
  display: flex;
  gap: 3rem;
  margin-top: 3rem;
}

.contact-links a {
  font-family: var(--font-sans);
  font-size: 1rem;
  font-weight: 400;
  color: var(--text-secondary);
  position: relative;
  padding-bottom: 2px;
  transition: color 0.3s var(--transition-smooth);
}

.contact-links a::after {
  content: '';
  position: absolute;
  bottom: 0;
  left: 0;
  width: 0;
  height: 1px;
  background: var(--text-primary);
  transition: width 0.4s var(--transition-smooth);
}

.contact-links a:hover {
  color: var(--text-primary);
}

.contact-links a:hover::after {
  width: 100%;
}

/* ============================================
   FOOTER
   ============================================ */

.site-footer {
  padding: 3rem 2.5rem;
  border-top: 1px solid var(--border-light);
  max-width: 1400px;
  margin: 0 auto;
  display: flex;
  justify-content: space-between;
  align-items: center;
}

.footer-copy {
  font-family: var(--font-sans);
  font-size: 0.8125rem;
  color: var(--text-muted);
}

.footer-links {
  display: flex;
  gap: 2rem;
}

.footer-links a {
  font-family: var(--font-sans);
  font-size: 0.8125rem;
  color: var(--text-muted);
  transition: color 0.3s var(--transition-smooth);
}

.footer-links a:hover {
  color: var(--text-primary);
}

/* ============================================
   RESPONSIVE
   ============================================ */

@media (max-width: 1024px) {
  .media-triptych {
    grid-template-columns: 1fr 1.5fr 1fr;
    gap: 1rem;
  }

  .about-grid {
    grid-template-columns: 200px 1fr;
    gap: 3rem;
  }

  .philosophy-grid {
    gap: 4rem;
  }

  .clients-grid {
    grid-template-columns: repeat(2, 1fr);
  }
}

@media (max-width: 768px) {
  .site-header {
    padding: 1.25rem 1.5rem;
  }

  .desktop-nav {
    display: none;
  }

  .menu-toggle {
    display: flex;
  }

  .hero {
    padding: 3rem 1.5rem 4rem;
    min-height: auto;
  }

  .section,
  .section-narrow {
    padding: 4rem 1.5rem;
  }

  .media-showcase {
    padding: 0 1.5rem 3rem;
  }

  .media-triptych {
    grid-template-columns: 1fr;
    gap: 1rem;
  }

  .media-block {
    aspect-ratio: 16/9;
  }

  .about-grid {
    grid-template-columns: 1fr;
    gap: 1.5rem;
  }

  .philosophy-grid {
    grid-template-columns: 1fr;
    gap: 2rem;
  }

  .philosophy-body {
    padding-top: 0;
  }

  .service-item {
    grid-template-columns: 1fr;
    gap: 1rem;
  }

  .clients-grid {
    grid-template-columns: 1fr;
    gap: 2.5rem;
  }

  .contact-links {
    flex-direction: column;
    gap: 1.5rem;
  }

  .site-footer {
    flex-direction: column;
    gap: 1rem;
    text-align: center;
    padding: 2rem 1.5rem;
  }

  .letter-header,
  .letter-content {
    padding-left: 1.5rem;
    padding-right: 1.5rem;
  }
}

@media (prefers-reduced-motion: reduce) {
  .marquee-track {
    animation: none !important;
  }
}

// ============================================
// Volta Studio — Main JavaScript
// ============================================

(function () {
  'use strict';

  // Mobile menu toggle
  const menuToggle = document.querySelector('.menu-toggle');
  const mobileOverlay = document.querySelector('.mobile-overlay');

  if (menuToggle && mobileOverlay) {
    menuToggle.addEventListener('click', function () {
      const isOpen = menuToggle.classList.toggle('open');
      mobileOverlay.classList.toggle('open', isOpen);
      document.body.style.overflow = isOpen ? 'hidden' : '';
    });

    // Close menu on link click
    mobileOverlay.querySelectorAll('a').forEach(function (link) {
      link.addEventListener('click', function () {
        menuToggle.classList.remove('open');
        mobileOverlay.classList.remove('open');
        document.body.style.overflow = '';
      });
    });
  }

  // Header scroll state
  const header = document.querySelector('.site-header');
  if (header) {
    let lastScroll = 0;
    window.addEventListener('scroll', function () {
      const currentScroll = window.pageYOffset;
      if (currentScroll > 20) {
        header.classList.add('scrolled');
      } else {
        header.classList.remove('scrolled');
      }
      lastScroll = currentScroll;
    }, { passive: true });
  }

  // Marquee: duplicate content for seamless loop
  document.querySelectorAll('.marquee-row').forEach(function (row) {
    const track = row.querySelector('.marquee-track');
    if (track) {
      track.innerHTML += track.innerHTML;
    }
  });
})();
